import { z } from "zod";

import { addLocalCalendarDays, localDateSchema } from "./date.js";

export const FOOD_NAME_MAX_LENGTH = 100;
export const FOOD_UNIT_MAX_LENGTH = 20;
export const FOOD_NOTES_MAX_LENGTH = 500;
